public int[][] FloodFill(int[][] image, int sr, int sc, int color) {
    int start = image[sr][sc];
    if (start != color) Fill(image, sr, sc, start, color);
    return image;
}

private void Fill(int[][] img, int r, int c, int from, int to) {
    if (r < 0 || c < 0 || r >= img.Length || c >= img[0].Length || img[r][c] != from) return;
    img[r][c] = to;                  // покрасили — значит, посетили
    Fill(img, r + 1, c, from, to);   // вниз
    Fill(img, r - 1, c, from, to);   // вверх
    Fill(img, r, c + 1, from, to);   // вправо
    Fill(img, r, c - 1, from, to);   // влево
}

