static readonly int[] DR = { 1, -1, 0, 0 }, DC = { 0, 0, 1, -1 };
readonly Stack<(int r, int c)> stack = new Stack<(int r, int c)>();

void Sink(char[][] g, int r0, int c0) {
    g[r0][c0] = '0';                        // пометка при добавлении
    stack.Push((r0, c0));
    while (stack.Count > 0) {
        var (r, c) = stack.Pop();
        for (int d = 0; d < 4; d++) {
            int y = r + DR[d], x = c + DC[d];
            if ((uint)y >= (uint)g.Length || (uint)x >= (uint)g[0].Length || g[y][x] != '1') continue;
            g[y][x] = '0';                  // второй раз её никто не положит
            stack.Push((y, x));
        }
    }
}

