var queue = new Queue<(int r, int c)>();
img[sr][sc] = color;
queue.Enqueue((sr, sc));
while (queue.Count > 0) {
    var (r, c) = queue.Dequeue();          // самая старая клетка — ближайшая к старту
    for (int d = 0; d < 4; d++) {
        int y = r + DR[d], x = c + DC[d];
        if ((uint)y >= (uint)img.Length || (uint)x >= (uint)img[0].Length || img[y][x] != from) continue;
        img[y][x] = color;                  // тоже при добавлении
        queue.Enqueue((y, x));
    }
}

